parameters.content:
### FLOW 1 — authenticated checkout
POST /webhook/fastpay/order-create
Authorization: Bearer <Supabase access token>

Ad: { purpose: "ad_checkout", orderId, currency: "IQD", ad: { daily_budget, days }, promoId?, promoCode?, note? }
Wallet: { purpose: "wallet_deposit", orderId, currency: "IQD", billAmount, note? }

The user id always comes from Supabase Auth. Ad prices always come from pa_quote_ad_checkout; the phone can choose an amount only for a wallet deposit.

parameters.jsCode:
const raw = $input.item.json;
let body = raw.body !== undefined ? raw.body : raw;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (_) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const q = raw.query || {};
const headers = raw.headers || {};
const pick = (a, b) => body[a] !== undefined ? body[a]
  : body[b] !== undefined ? body[b]
  : q[a] !== undefined ? q[a] : q[b];

const orderId = pick('orderId', 'order_id');
const currency = pick('currency', 'currency') || 'IQD';
const inferredPurpose = body.ad && typeof body.ad === 'object'
  ? 'ad_checkout' : 'wallet_deposit';
const purpose = String(body.purpose || inferredPurpose).trim().toLowerCase();
const noteDefault = purpose === 'ad_checkout'
  ? 'Proxo ad payment' : 'Proxo wallet deposit';
const note = pick('note', 'note') || noteDefault;
const billAmount = Number(pick('billAmount', 'bill_amount'));
const ad = body.ad && typeof body.ad === 'object' && !Array.isArray(body.ad)
  ? body.ad : {};
const dailyBudget = Number(ad.daily_budget);
const days = Number(ad.days);
const promoId = body.promoId || body.promo_id || null;
const promoCode = body.promoCode || body.promo_code || null;
const authorization = String(headers.authorization || headers.Authorization || '').trim();
const fail = (error) => [{ json: { valid: false, error } }];

if (!/^Bearer\s+\S+$/i.test(authorization)) return fail('A valid Supabase bearer token is required');
if (!orderId || !/^[A-Za-z0-9_-]{8,32}$/.test(String(orderId))) {
  return fail('orderId must be 8-32 safe characters');
}
if (!['ad_checkout', 'wallet_deposit'].includes(purpose)) return fail('Invalid checkout purpose');
if (String(currency).toUpperCase() !== 'IQD') return fail('Only IQD is supported');
if (purpose === 'ad_checkout') {
  if (![10,20,50,100,200,500,1000].includes(dailyBudget)) return fail('Invalid daily budget');
  if (!Number.isInteger(days) || days < 1 || days > 7) return fail('Invalid ad duration');
} else if (!Number.isInteger(billAmount) || billAmount < 5000 || billAmount > 100000000) {
  return fail('Wallet deposit amount must be 5,000-100,000,000 IQD');
}

return [{ json: {
  valid: true,
  purpose,
  orderId: String(orderId),
  currency: 'IQD',
  note: String(note).slice(0, 300),
  billAmount: purpose === 'wallet_deposit' ? billAmount : null,
  ad: purpose === 'ad_checkout' ? { daily_budget: dailyBudget, days } : null,
  promoId: purpose === 'ad_checkout' && promoId ? String(promoId) : null,
  promoCode: purpose === 'ad_checkout' && promoCode
    ? String(promoCode).trim().slice(0, 80) : null,
  authorization,
} }];

const b = $input.item.json.body || $input.item.json;
return [{ json: {
  gw_transaction_id: b.gw_transaction_id,
  merchant_order_id: b.merchant_order_id,
  received_amount: Number(b.received_amount),
  currency: b.currency,
  status: (b.status || '').toLowerCase(),
  customer_name: b.customer_name,
  customer_mobile_number: b.customer_mobile_number,
  at: b.at
} }];

// ---- parse the validate response (same quirks as the QR endpoint) ----
const vRes    = $('Validate Payment').item.json;
const vStatus = vRes.statusCode !== undefined ? vRes.statusCode : 200;
const vRawSrc = vRes.body !== undefined ? vRes.body : (vRes.data !== undefined ? vRes.data : vRes.text);
const vRaw    = (typeof vRawSrc === 'string' ? vRawSrc : JSON.stringify(vRawSrc || {})).trim();

let validateResp = null;
let parseError   = null;
if (!vRaw || vRaw.startsWith('<')) {
  parseError = 'FastPay validate returned a non-JSON body (HTTP ' + vStatus + ')';
} else {
  try {
    validateResp = JSON.parse(vRaw);
  } catch (e) {
    // repair the documented missing comma after "errors": []
    try { validateResp = JSON.parse(vRaw.replace(/("errors"\s*:\s*\[[^\]]*\])\s*(?=")/, '$1,')); }
    catch (e2) { parseError = 'Invalid JSON from FastPay validate: ' + e.message; }
  }
}

const ipn   = $('Extract IPN Data').item.json;
const rows  = $input.all().map(i => i.json).filter(r => r && r.id);
const order = rows[0];

let match = false, duplicate = false, retryable = false, reason = '';

if (!order) {
  // an unknown order id is almost always a forged / replayed IPN, but it is
  // never a reason to brand a real order as fraud - nothing to update anyway
  reason = 'Order not found in pa_transactions';
  retryable = true;
} else if (order.wallet_credited === true) {
  duplicate = true;
  reason = 'Wallet already credited for this order';
} else if (['REFUNDED', 'REFUND_FAILED'].includes(order.gateway_status)) {
  duplicate = true;
  reason = 'Order already refunded';
} else if (parseError) {
  reason = parseError;
  retryable = true;                       // our problem, not the customer's
} else if (Number(validateResp.code) !== 200) {
  reason = 'Validation API returned code ' + validateResp.code;
  retryable = true;                       // transient gateway/API failure
} else {
  const data = validateResp.data || {};
  const amountMatches   = Number(data.received_amount) === Number(order.gateway_amount != null ? order.gateway_amount : order.amount);
  const currencyMatches = String(data.currency || '').toUpperCase() === String(order.currency || 'IQD').toUpperCase();
  const SUCCESS = ['success', 'paid', 'completed', 'approved'];
  // only the server-to-server response counts - the IPN body is attacker-controlled
  const statusOk = SUCCESS.includes(String(data.status || data.payment_status || '').toLowerCase());

  if (amountMatches && currencyMatches && statusOk) {
    match = true;
  } else if (!statusOk) {
    // gateway says it is not paid: not fraud, just not settled yet
    reason = 'Gateway does not report this order as paid (status=' + (data.status || data.payment_status || 'unknown') + ')';
    retryable = true;
  } else {
    // paid, but for the wrong amount or currency - this one IS suspicious
    reason = 'Mismatch amount=' + amountMatches + ' currency=' + currencyMatches;
    retryable = false;
  }
}

return [{ json: {
  match,
  duplicate,
  retryable,
  reason,
  orderId:         ipn.merchant_order_id,
  transactionId:   order ? order.id : null,
  userId:          order ? order.user_id : null,
  gwTransactionId: ipn.gw_transaction_id,
  receivedAmount:  ipn.received_amount,
  currency:        ipn.currency,
  validateData:    validateResp ? (validateResp.data || null) : null,
  ipn,
} }];

const raw     = $input.item.json;
const b       = raw.body || raw;

// Header authentication is enforced by the Refund Webhook node.
const orderId = b.orderId;
const msisdn  = b.msisdn;
const amount  = b.amount;
const deductWallet = b.deductWallet === undefined ? true : Boolean(b.deductWallet);

if (!orderId || !msisdn || amount === undefined || amount === null) {
  return [{ json: { valid: false, error: 'orderId, msisdn and amount are required' } }];
}
if (!(Number(amount) > 0)) {
  return [{ json: { valid: false, error: 'amount must be a positive number' } }];
}

return [{ json: {
  valid: true,
  orderId: String(orderId),
  msisdn: String(msisdn),
  amount: Number(amount),
  deductWallet,
} }];

