// FastPay's QR endpoint returned a body n8n could not parse.
// Handle: HTML/gateway errors, non-200s, and the missing comma after
// "errors": [] that appears in FastPay's own documented sample.
const res    = $input.item.json;
const status = res.statusCode !== undefined ? res.statusCode : 200;
const rawSrc = res.data !== undefined ? res.data
            : (res.body !== undefined ? res.body : res.text);
const raw    = typeof rawSrc === 'string' ? rawSrc : JSON.stringify(rawSrc || {});
const trimmed = raw.trim();

const bail = (msg) => [{ json: {
  code: status,
  messages: msg,
  errors: [msg],
  data: null,
  rawBody: trimmed.slice(0, 500),
} }];

if (!trimmed) return bail('Empty response from FastPay (HTTP ' + status + ')');

if (trimmed.startsWith('<')) {
  return bail('FastPay returned HTML, not JSON (HTTP ' + status + ') - check the URL and that the host is reachable');
}

let parsed = null;
try {
  parsed = JSON.parse(trimmed);
} catch (e) {
  // repair the documented missing comma:  "errors": []  "data": {...}
  const repaired = trimmed.replace(/("errors"\s*:\s*\[[^\]]*\])\s*(?=")/, '$1,');
  try {
    parsed = JSON.parse(repaired);
  } catch (e2) {
    return bail('FastPay response is not valid JSON (HTTP ' + status + '): ' + e.message);
  }
}

if (parsed.code === undefined) parsed.code = status;
parsed.httpStatus = status;
parsed.rawBody = trimmed.slice(0, 500);
parsed.responseHeaders = res.headers || {};
if (!Array.isArray(parsed.errors)) parsed.errors = parsed.errors ? [parsed.errors] : [];

return [{ json: parsed }];

// FastPay's status endpoint has the same JSON quirks as the QR endpoint.
// Normalise everything here so the IF nodes downstream stay simple.
const res    = $input.item.json;
const status = res.statusCode !== undefined ? res.statusCode : 200;
const rawSrc = res.data !== undefined ? res.data : (res.body !== undefined ? res.body : res.text);
const raw    = typeof rawSrc === 'string' ? rawSrc : JSON.stringify(rawSrc || {});
const trimmed = raw.trim();
const out = (o) => [{ json: o }];

if (!trimmed || trimmed.startsWith('<')) {
  return out({ ok:false, reason:'FastPay returned a non-JSON body (HTTP ' + status + ')', httpStatus:status, paymentStatus:'', raw:trimmed.slice(0,300) });
}

let parsed = null;
try {
  parsed = JSON.parse(trimmed);
} catch (e) {
  const repaired = trimmed.replace(/("errors"\s*:\s*\[[^\]]*\])\s*(?=")/, '$1,');
  try { parsed = JSON.parse(repaired); }
  catch (e2) { return out({ ok:false, reason:'Invalid JSON from FastPay: ' + e.message, httpStatus:status, paymentStatus:'', raw:trimmed.slice(0,300) }); }
}

const code = parsed.code !== undefined ? Number(parsed.code) : status;
const data = (parsed.data && typeof parsed.data === 'object') ? parsed.data : {};
const pick = (...keys) => {
  for (const k of keys) {
    if (data[k] !== undefined && data[k] !== null && data[k] !== '') return data[k];
    if (parsed[k] !== undefined && parsed[k] !== null && parsed[k] !== '') return parsed[k];
  }
  return null;
};

const paymentStatus = String(pick('payment_status','paymentStatus','status','transaction_status','transactionStatus') || '').trim().toUpperCase();

return out({
  ok: code === 200,
  code,
  httpStatus: status,
  paymentStatus,
  gwTransactionId: pick('gw_transaction_id','gwTransactionId','transaction_id','transactionId'),
  receivedAmount: pick('received_amount','receivedAmount','amount'),
  currency: pick('currency') || 'IQD',
  messages: parsed.messages || null,
  data,
  raw: trimmed.slice(0,300),
});

const req  = $('Validate Refund Input').item.json;
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const tx   = rows[0];

const deny = (code, msg) => [{ json: { allowed: false, code, message: msg, orderId: req.orderId } }];

if (!tx) return deny('ORDER_NOT_FOUND', 'No such order');
if (tx.gateway_status === 'REFUNDED') return deny('ALREADY_REFUNDED', 'This order was already refunded');
// the guard that was missing: never ask FastPay to refund money that never arrived
if (!(tx.wallet_credited === true || tx.gateway_status === 'PAID')) {
  return deny('ORDER_NOT_PAID', 'Order was never paid (gateway_status=' + tx.gateway_status + ')');
}

const paidIqd = Number(tx.received_amount != null ? tx.received_amount : tx.gateway_amount);
if (Number(req.amount) > paidIqd) {
  return deny('REFUND_EXCEEDS_PAYMENT', 'Requested ' + req.amount + ' IQD but only ' + paidIqd + ' IQD was paid');
}

return [{ json: { allowed: true, orderId: req.orderId, paidIqd, transactionId: tx.id } }];

const raw = $input.item.json;
let body = raw.body !== undefined ? raw.body : raw;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (_) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const headers = raw.headers || {};
const orderId = body.orderId || body.order_id;
const authorization = String(headers.authorization || headers.Authorization || '').trim();
const valid = /^[A-Za-z0-9_-]{8,32}$/.test(String(orderId || ''))
  && /^Bearer\s+\S+$/i.test(authorization);
return [{ json: {
  valid,
  orderId: orderId ? String(orderId) : '',
  authorization,
  error: valid ? null : 'orderId and a valid Supabase bearer token are required',
} }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const tx = rows[0] || null;
return [{ json: {
  found: !!tx,
  orderId: $('Validate Status Request').item.json.orderId,
  tx,
} }];

const res = $input.item.json;
const httpStatus = res.statusCode !== undefined ? res.statusCode : 200;
const src = res.data !== undefined ? res.data : (res.body !== undefined ? res.body : res.text);
const raw = typeof src === 'string' ? src.trim() : JSON.stringify(src || {});
let parsed = {};
try { parsed = raw && !raw.startsWith('<') ? JSON.parse(raw) : {}; }
catch (_) {
  try { parsed = JSON.parse(raw.replace(/("errors"\s*:\s*\[[^\]]*\])\s*(?=")/, '$1,')); }
  catch (_) { parsed = {}; }
}
const data = parsed.data && typeof parsed.data === 'object' ? parsed.data : {};
const pick = (...keys) => {
  for (const key of keys) {
    if (data[key] !== undefined && data[key] !== null && data[key] !== '') return data[key];
    if (parsed[key] !== undefined && parsed[key] !== null && parsed[key] !== '') return parsed[key];
  }
  return null;
};
return [{ json: {
  ok: Number(parsed.code ?? httpStatus) === 200,
  orderId: $('Normalize App Payment').item.json.orderId,
  transactionId: $('Normalize App Payment').item.json.tx.id,
  paymentStatus: String(pick('payment_status','paymentStatus','status','transaction_status','transactionStatus') || '').trim().toUpperCase(),
  gwTransactionId: pick('gw_transaction_id','gwTransactionId','transaction_id','transactionId'),
  receivedAmount: pick('received_amount','receivedAmount','amount'),
  currency: pick('currency') || 'IQD',
  data,
} }];

parameters.responseBody:
={{ {
    "success": $json.ok === true,
    "orderId": $('Parse FastPay App Status').item.json.orderId,
    "transactionId": $json.transaction_id || $('Parse FastPay App Status').item.json.transactionId,
    "status": $json.status || "approved",
    "gatewayStatus": $json.gateway_status || "PAID",
    "paid": $json.ok === true,
    "terminal": true
  } }}

={{ {
    "success": true,
    "orderId": $('Parse FastPay App Status').item.json.orderId,
    "transactionId": $json.transaction_id || $('Parse FastPay App Status').item.json.transactionId,
    "status": "rejected",
    "gatewayStatus": $json.gateway_status || $('Parse FastPay App Status').item.json.paymentStatus,
    "paid": false,
    "terminal": true
  } }}

parameters.jsCode:
const req = $('Validate & Prepare').item.json;
const user = $('Verify App User').item.json;
const isAd = req.purpose === 'ad_checkout';
const quote = isAd ? $input.item.json : {};
const billAmount = Number(isAd ? quote.amount_iqd : req.billAmount);
if (!Number.isInteger(billAmount) || billAmount <= 0) {
  throw new Error('Resolved checkout amount is invalid');
}
return [{ json: {
  purpose: req.purpose,
  orderId: req.orderId,
  currency: req.currency,
  note: req.note,
  userId: user.id,
  billAmount,
  costUsd: isAd ? quote.cost_usd : null,
  rate: isAd ? quote.rate : null,
} }];
